NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: '§ Pavel, apostol Jezusa Kristusa po zapovedi Boga, našega Odrešenika in Gospoda Jezusa Kristusa, ki je naše upanje;',
        2: 'Timóteju, mojemu lastnemu sinu v veri: ›Milost, usmiljenje in mir od Boga, našega Očeta in Jezusa Kristusa, našega Gospoda.‹',
        3: 'Kakor sem te rotil, ko sem odšel v Makedonijo, da še ostaneš v Efezu, da bi lahko nekaterim naročil, da ne učijo nobenega drugega nauka,',
        4: 'niti ne dajo pozornosti bajkam in neskončnim rodovnikom, kar prej podpira razprave, kakor [pa] bogaboječe izgrajevanje, ki je v veri. Tako delajte.',
        5: 'Torej namen zapovedi je ljubezen iz čistega srca in iz dobre vesti ter iz nehlinjene vere,',
        6: 'od katere so se nekateri oddaljili in obrnili stran k praznemu blebetanju;',
        7: 'želeč biti učitelji postave; [pa] niti ne razumejo kaj govorijo niti o čemer zatrjujejo.',
        8: 'Toda mi vemo, da je postava dobra, če jo človek uporablja zakonito;',
        9: 'vedoč to, da postava ni narejena za pravičnega človeka, temveč za nepostavnega in neposlušnega, za brezbožnega in za grešnike, za nesvete in oskrunjene, za morilce očetov in morilce mater, za ubijalce,',
        10: 'za vlačugarje, za tiste, ki sebe omadežujejo z možmi, za ugrabitelje ljudi, za lažnivce, za krivoprisežnike in če je katerakoli druga stvar, ki je nasprotna zdravemu nauku;',
        11: 'glede na slavni evangelij blagoslovljenega Boga, ki je bil zaupan mojemu varstvu.',
        12: 'In zahvaljujem se Kristusu Jezusu, našemu Gospodu, ki me je usposobil in me postavil v službo, kajti imel me je za zvestega;',
        13: 'ki sem bil prej bogokletnik in preganjalec ter škodljivec. Toda dosegel sem usmiljenje, ker sem to počel nevedno, v nejeveri.',
        14: 'Milost našega Gospoda pa je bila silno bogata z vero in ljubeznijo, ki je v Kristusu Jezusu.',
        15: 'To je zvest izrek in vreden popolnega sprejetja, da je Kristus Jezus prišel na svet, da reši grešnike; od katerih sem jaz vodilni.',
        16: 'Vendar sem zaradi tega razloga dosegel usmiljenje, da bi Jezus Kristus lahko vnaprej na meni pokazal vso potrpežljivost za vzor tem, ki naj bi odslej verovali vanj za večno življenje.',
        17: 'Torej Kralju, večnemu, nesmrtnemu, nevidnemu, edinemu modremu Bogu, bodi čast in slava na veke vekov. Amen.',
        18: 'To naročilo sem zaupal tebi, sin Timótej, glede na prerokbe, ki so izšle poprej o tebi, da boš po njih lahko bojeval dober boj;',
        19: 'in obdržiš vero in dobro vest; ki so jo nekateri zavrgli in glede vere storili brodolom.',
        20: 'Od katerih sta Himénaj in Aleksander; ki sem ju izročil Satanu, da bi se lahko naučila ne preklinjati.',
    },
    2: {
        1: 'Predvsem torej spodbujam, da naj bodo ponižne prošnje, molitve, posredovanja in zahvaljevanja narejeni za vse ljudi;',
        2: 'za kralje in za vse, ki so na oblasti; da bomo lahko preživljali tiho in mirno življenje, v vsej bogaboječnosti in poštenosti.',
        3: 'Kajti to je dobro in sprejemljivo v očeh Boga, našega Odrešenika,',
        4: 'ki hoče, da bi bili vsi ljudje rešeni in da pridejo do spoznanja resnice.',
        5: 'Kajti obstaja en Bog in en posrednik med Bogom in ljudmi, človek Kristus Jezus;',
        6: 'ki je samega sebe dal v odkupnino za vse, da se bo pričevalo ob primernem času.',
        7: '§ Kateremu sem določen za pridigarja in apostola (govorim resnico v Kristusu in ne lažem), učitelja poganov v veri in resnici.',
        8: 'Hočem torej, da možje povsod molijo, vzdigujoč svete roke, brez besa in dvoma.',
        9: 'In da na podoben način tudi ženske sebe olepšajo s preprosto obleko, s sramežljivostjo in preudarnostjo; ne s prepletanjem las ali zlatom ali biseri ali dragim oblačilom;',
        10: 'temveč (kar je primerno ženskam, ki izražajo bogaboječnost) z dobrimi deli.',
        11: 'Naj se ženska pouči v tišini z vso podložnostjo.',
        12: 'Toda ženski ne dovolim poučevati niti da si prisvoji oblast nad moškim, ampak, da je v tišini.',
        13: 'Kajti najprej je bil oblikovan Adam, potem Eva.',
        14: 'In ni bil zaveden Adam, temveč ženska, ki je bila zavedena v prestopek.',
        15: 'Vendar pa bo rešena z rojevanjem, če oni nadaljujejo v veri in ljubezni in svetosti s preudarnostjo.',
    },
    3: {
        1: 'To je zvest izrek: »Če človek hrepeni po službi duhovnega nadzornika, želi dobro delo.«',
        2: 'Duhovni nadzornik mora biti torej brez krivde, soprog ene žene, oprezen, trezen, dobrega vedênja, predan gostoljubnosti, zmožen za poučevanje.',
        3: '§ Ne vdan vinu, ne razuzdanec, ne pohlepen ali umazano grabežljiv; temveč potrpežljiv, ne razgrajač, ne lakomen;',
        4: 'tisti, ki dobro vodi svojo lastno družino, ima svoje otroke v podložnosti z vso resnostjo;',
        5: '(kajti če mož ne ve, kako vladati svoji lastni hiši, kako bo skrbel za Božjo cerkev?)',
        6: 'Ne novinec, da ne bi, kipeč od ponosa, padel v hudičevo obsodbo.',
        7: 'Poleg tega mora imeti dober glas od teh, ki so zunaj; da ne pade v grajo ter v hudičevo zanko.',
        8: 'Prav tako morajo biti pomočniki [Božjih] služabnikov dostojanstveni, ne dvoumnih besed, ne vdani obilnemu vinu, ne pohlepni po umazani grabežljivosti;',
        9: 'ki s čisto vestjo obdržijo skrivnost vere.',
        10: 'In ti naj bodo najprej preizkušeni; potem pa naj, najdeni brez krivde, služijo kot pomočniki [Božjega] služabnika.',
        11: 'Prav tako morajo biti njihove žene dostojanstvene, ne obrekovalke, trezne, zveste v vseh stvareh.',
        12: 'Naj bodo pomočniki [Božjih] služabnikov soprogi ene žene, ki dobro vladajo svojim otrokom in svoji lastni hiši.',
        13: 'Kajti tisti, ki so se pravilno posluževali službe pomočnika [Božjega] služabnika, so si pridobili dober položaj in veliko hrabrost v veri, ki je v Kristusu Jezusu.',
        14: 'Te stvari ti pišem, ker upam, da v kratkem pridem k tebi.',
        15: 'Toda če se bom dolgo mudil, da boš lahko vedel, kako bi se moral obnašati v Božji hiši, ki je cerkev živega Boga, steber in temelj resnice.',
        16: '§ In skrivnost prave bogaboječnosti je brez polemike velika. Bog je bil razodet v mesu, opravičen v Duhu, viden od angelov, oznanjen poganom, svet je vanj veroval, sprejet je bil gor v slavo.',
    },
    4: {
        1: 'Duh torej izrecno govori, da bodo v poznejših časih nekateri odšli od vere in dajali pozornost zapeljivim duhovom in hudičevim naukom;',
        2: 'v hinavščini govoreč laži; ki imajo svojo vest ožgano z vročim železom;',
        3: 'prepovedovali bodo poročanje in zapovedovali vzdržati se jedi, ki jih je Bog ustvaril, da bi bile sprejete z zahvaljevanjem teh, ki verujejo in poznajo resnico.',
        4: 'Kajti vsako Božje bitje je dobro in nič naj ne bo odklonjeno, če je to sprejeto z zahvaljevanjem,',
        5: 'kajti posvečeno je z Božjo besedo in molitvijo.',
        6: 'Če brate spominjaš na te stvari, boš dober služabnik Jezusa Kristusa, hranjen z besedami vere in zdravega nauka, ki si mu sledil.',
        7: 'Toda zavrni bajke oskrunjenih in starih žensk ter se raje uri v bogaboječnosti.',
        8: 'Kajti telesno urjenje malo koristi, toda bogaboječnost je koristna za vse stvari, ki ima obljubo življenja, ki je sedaj in tega, ki pride.',
        9: 'To je zvest izrek in vreden popolnega sprejetja.',
        10: 'Kajti zato se tako trudimo, kakor prenašamo grajo, ker zaupamo v živega Boga, ki je Odrešenik vseh ljudi, zlasti teh, ki verujejo.',
        11: 'Te stvari zapoveduj in uči.',
        12: 'Ne dopusti, da kdorkoli prezira tvojo mladost; temveč bodi zgled vernikom v besedi, vedênju, v ljubezni, v duhu, v veri, v čistosti.',
        13: 'Dokler ne pridem, daj pozornost branju, spodbujanju [in] nauku.',
        14: 'Ne zanemarjaj daru, ki je v tebi, ki ti je bil dan po prerokbi, s polaganjem rok zbora starešin.',
        15: '§ Premišljuj o teh stvareh; v celoti se jim izroči; da bo tvoj napredek lahko viden vsem.',
        16: 'Pazi nase in na nauk; nadaljuj v njih, kajti s takšnim ravnanjem boš rešil tako sebe kakor tudi tiste, ki te poslušajo.',
    },
    5: {
        1: 'Ne oštej starešine, temveč ga milo prosi kakor očeta; in mlajše može kakor brate,',
        2: 'starejše ženske kakor matere; mlajše kakor sestre, z vso čistostjo.',
        3: 'Spoštuj vdove, ki so zares vdove.',
        4: 'Toda če ima katerakoli vdova otroke ali nečake, naj se najprej naučijo doma pokazati spoštovanje in povračati svojim staršem; kajti to je dobro in sprejemljivo pred Bogom.',
        5: 'Torej tista, ki je zares vdova in zapuščena, zaupa v Boga ter noč in dan nadaljuje v ponižnih prošnjah ter molitvah.',
        6: 'Toda tista, ki živi v užitku, je mrtva, medtem ko živi.',
        7: 'In zapoveduj te stvari, da bodo lahko brez krivde.',
        8: 'Toda če kdorkoli ne skrbi za svoje lastne in [še] posebej za tiste iz svoje lastne hiše, je zanikal vero in je slabši kot nevernik.',
        9: 'Ne pustite, da bi bila sprejeta vdova z manj kot šestdesetimi leti, ki je bila žena enega moža,',
        10: 'z dobrim pričevanjem o dobrih delih; če je vzgajala otroke, če je prenočevala tujce, če je svetim umivala stopala, če je pomagala trpečim, če je marljivo sledila vsakemu dobremu delu.',
        11: 'Toda mlajše vdove zavrni, kajti ko začnejo postajati poltene, zoper Kristusa, se hočejo možiti;',
        12: 'imajo obsodbo, ker so zavrgle svojo prvo vero.',
        13: 'In poleg tega se naučijo biti brezdelne in se klatijo okoli od hiše do hiše; in ne samo brezdelja, temveč tudi klepetanja in vtikljivosti [v zadeve drugih], govoreč stvari, ki jih ne bi smele.',
        14: 'Hočem torej, da se mlajše ženske omožijo, rodijo otroke, vodijo hišo, ne dajo nobene priložnosti nasprotniku, da govori grajajoče.',
        15: 'Kajti nekatere so se že obrnile proč za Satanom.',
        16: 'Če ima katerikoli moški ali ženska, ki veruje, vdove, naj jih podpira in naj se ne obremenjuje cerkev, da bo ta lahko podpirala tiste, ki so zares vdove.',
        17: 'Naj bodo starešine, ki dobro vladajo, šteti za vredne dvojne časti, posebej tisti, ki se trudijo v besedi in nauku.',
        18: 'Kajti pismo pravi: ›Ne boš zavezal gobca volu, ki mane žito.‹ In: ‹Delavec je vreden svoje nagrade.‹',
        19: 'Proti starešini ne sprejmi obtožbe, razen pred dvema ali tremi pričami.',
        20: 'Te, ki grešijo, oštej pred vsemi, da se bodo tudi drugi lahko bali.',
        21: '§ Naročam ti pred Bogom in Gospodom Jezusom Kristusom in izvoljenimi angeli, da obeležuješ te stvari, brez dajanja prednosti enemu pred drugim in ničesar ne delaj s pristranskostjo.',
        22: 'Na nobenega človeka naglo ne polagaj rok niti ne bodi soudeleženec grehov drugih ljudi. Sebe ohrani čistega.',
        23: 'Ne pij več vode, temveč zaradi trebuha in svojih pogostih slabotnosti užij malce vina.',
        24: 'Grehi nekaterih ljudi so razkriti vnaprej in gredo prej na sodbo; in [grehi] nekaterih ljudi sledijo kasneje.',
        25: 'Podobno so tudi dobra dela nekaterih vnaprej razodeta; in tista, ki so drugačna, ne morejo biti skrita.',
    },
    6: {
        1: 'Toliko služabnikov, kot jih je podjarmljenih, naj imajo svoje lastne gospodarje za vredne vse časti, da se zoper Božje ime in njegov nauk ne bi izrekalo bogokletje.',
        2: 'In tisti, ki imajo verne gospodarje, naj jih ne prezirajo zato, ker so bratje; temveč naj jim raje služijo, ker so zvesti in ljubljeni, soudeleženci dobička. Te stvari úči in spodbujaj.',
        3: 'Če katerikoli človek uči drugače in ne pritrjuje zdravim besedam, celó besedam našega Gospoda Jezusa Kristusa in nauku, ki je glede na bogaboječnost;',
        4: 'je ponosen in ničesar ne ve, marveč boleha glede vprašanj in besednih prepirov, od česar prihajajo zavist, prepir, posmehovanja, hudobna domnevanja,',
        5: '§ sprevržena razpravljanja ljudi izprijenih misli in oropanih resnice, ki mislijo, da je bogaboječnost [vir] dobička. Od takšnih se umaknite.',
        6: '§ Toda bogaboječnost je, skupaj z zadovoljstvom, velik dobiček.',
        7: 'Kajti ničesar nismo prinesli na ta svet in nedvomno je, [da] ničesar ne moremo odnesti.',
        8: 'In bodimo zadovoljni s tem, da imamo hrano in obleko.',
        9: 'Toda tisti, ki hočejo biti bogati, padejo v skušnjavo in zanko ter v mnoga nespametna in škodljiva poželenja, ki ljudi potopijo v uničenje in pogubo.',
        10: 'Kajti ljubezen do denarja je korenina vsega zla; za katerim so nekateri zahlepeli, zašli od vere in se prebodli z mnogimi bridkostmi.',
        11: 'Toda ti, oh Božji mož, beži od teh stvari in si prizadevaj za pravičnost, bogaboječnost, vero, ljubezen, potrpežljivost in krotkost.',
        12: 'Bojuj dober boj vere, oprimi se večnega življenja, kamor si tudi poklican in si pred mnogimi pričami izpovedal dobro izpoved.',
        13: 'Dajem ti naročilo v očeh Boga, ki oživlja vse stvari in pred Kristusom Jezusom, ki je pred Poncijem Pilatom pričeval dobro priznanje;',
        14: 'da ohraniš to zapoved brez madeža, brezgrajno do pojavitve našega Gospoda Jezusa Kristusa,',
        15: 'ki jo bo ob svojih časih pokazal, ki je blagoslovljen in edini Vladar, Kralj kraljev in Gospod gospodov;',
        16: 'ki ima edini nesmrtnost in prebiva v svetlobi, ki sem mu noben človek ne more približati; katerega noben človek ni videl niti ne more videti; njemu bodi čast in večna oblast. Amen.',
        17: 'Naročajte tem, ki so na tem svetu bogati, da naj ne bodo vzvišeni niti naj ne zaupajo v negotova bogastva, temveč v živega Boga, ki nam bogato daje v uživanje vse stvari;',
        18: 'da delajo dobro, da bodo bogati v dobrih delih, pripravljeni za razdeljevanje, voljni za posredovanje;',
        19: 'in si v shrambi privarčevali dober temelj za čas, ki pride, da se bodo lahko oprijeli večnega življenja.',
        20: '§ Oh Timótej, varuj to, kar je zaupano tvojemu varstvu, izogibajoč se oskrunjenih in praznih blebetanj ter tako imenovanih lažnih znanstvenih oporekanj,',
        21: '§ ki so jih nekateri izpovedovali in zašli glede vere. Milost bodi s teboj. Amen. [Prvo Timóteju je bilo napisano iz Laodikeje, ki je glavno mesto Frigije Pacatiane.]',
    },
}
